mapper.select:
select 
from edu_class_schedule s
left join sys_user u on u.id = s.teacher_id
where s.class_id = #{classId}
  and s.schedule_date >= #{startDate}
  and s.schedule_date <= #{endDate}
order by s.schedule_date asc, s.id asc

select from edu_class_schedule s left join sys_user u on u.id = s.teacher_id where s.class_id in
#{classId}
order by s.class_id asc, s.schedule_date asc, s.id asc

select s.teacher_id, coalesce(u.real_name, u.nickname, u.username) as teacher_name, s.schedule_date, s.class_id, c.class_term, s.stage_name from edu_class_schedule s left join sys_user u on u.id = s.teacher_id left join edu_class c on c.id = s.class_id where s.schedule_type = 'CLASS' and s.teacher_id is not null and s.schedule_date >= #{startDate} and s.schedule_date <= #{endDate} and s.teacher_id in
#{teacherId}
order by s.teacher_id asc, s.schedule_date asc, s.class_id asc, s.id asc

mapper.update:
update edu_class_schedule
set teacher_id = #{teacherId},
    updated_at = now()
where class_id = #{classId}
  and stage_name = #{stageName}
  and schedule_type = 'CLASS'

update edu_class_schedule
set course_content = #{courseContent},
    updated_at = now()
where class_id = #{classId}
  and schedule_date = #{scheduleDate}
  and schedule_type = 'CLASS'

update edu_class_schedule
set teacher_id = #{teacherId},
    updated_at = now()
where class_id = #{classId}
  and schedule_date = #{scheduleDate}
  and schedule_type = 'CLASS'

mapper.delete:
delete from edu_class_schedule
where class_id = #{classId}
  and schedule_date >= #{startDate}
